/**
 * The emails whose wording tenants can change (Admin > Email templates),
 * with the built-in English and Arabic wording each one falls back to.
 *
 * A template is plain text with a little markup (see render.ts):
 *   {{name}}          a variable (the workflow screen's {name} also works)
 *   **bold**          bold text
 *   [label](url)      a link; alone on a line it becomes a button
 *   a blank line      a new paragraph
 * A "block" variable (e.g. the quotation table) is generated by the platform
 * and placed on its own line.
 *
 * Adding an email: add its entry here, then send it with renderEmail()
 * (src/lib/email-templates/index.ts) using the same key and variables.
 * Pure data, safe to import from client components.
 */

export const EMAIL_LOCALES = ['en', 'ar'] as const;
export type EmailLocale = (typeof EMAIL_LOCALES)[number];

export interface TemplateVariable {
  name: string;
  description: string;
  sample: string;
  /** Generated HTML placed as its own paragraph (the sample is text only). */
  block?: boolean;
  /** Used when the value is empty, per language. */
  fallback?: Partial<Record<EmailLocale, string>>;
}

export interface EmailTemplateDef {
  key: string;
  module: string;
  name: string;
  description: string;
  variables: TemplateVariable[];
  defaults: Record<EmailLocale, { subject: string; body: string }>;
}

